<script>
import axios from 'axios'
import FunctionCard from './components/FunctionCard.vue'
import YzpzCard from './components/YzpzCard.vue'
import BankFlowCard from './components/BankFlowCard.vue'
import CommentCard from './components/CommentCard.vue'
import ToolboxCard from './components/ToolboxCard.vue'
import JxkhCard from './components/JxkhCard.vue'
import GzbPipeiCard from './components/GzbPipeiCard.vue'
import GzbcfCard from './components/GzbcfCard.vue'
import CxmSummaryCard from './components/CxmSummaryCard.vue'
import HomePage from './components/HomePage.vue'
import AiChatBot from './components/AiChatBot.vue'

export default {
  name: 'App',
  components: { FunctionCard, YzpzCard, BankFlowCard, CommentCard, ToolboxCard, JxkhCard, GzbPipeiCard, GzbcfCard, CxmSummaryCard, HomePage, AiChatBot },
  data() {
    return {
      activeMenu: 'home'
    }
  },
  methods: {
    handleMenuSelect(index) {
      this.activeMenu = index
    },
    handleProcess({ endpoint, formData, onSuccess, onError }) {
      // 由子组件触发，统一处理上传逻辑
      // FormData 上传不能手动设置 Content-Type，浏览器会自动设置并带上 boundary
      axios.post(endpoint, formData).then(res => {
        if (res.data.success) {
          onSuccess(res.data)
        } else {
          onError(res.data.message || '处理失败')
        }
      }).catch(err => {
        onError(err.response?.data?.message || err.message)
      })
    }
  }
}
</script>

